import { useRef } from "react";
import { useOnSettled } from "../hooks/useOnSettled";
import { emitStepEvent } from "./events";

/** Emits navigate-finish once, when the page's first data has been committed. */
export function useNavigateFinishEvent(page: unknown): void {
  const finished = useRef(false);
  useOnSettled(page, () => {
    if (finished.current) return;
    finished.current = true;
    emitStepEvent("navigate-finish");
  });
}

/**
 * Emits the step events of a list that loads in pages, after their content
 * has been committed: continuation-applied when it has more pages than it
 * had, and, for a list that reloads, reload-applied for its first data
 * under a new `reloadKey`. Data that is already there when the list mounts,
 * from the cache, counts as shown.
 *
 * @param data The list's loaded pages, or undefined while there are none
 *   (placeholder data counts as none).
 * @param reloadKey Identifies what the list was loaded from, such as a sort
 *   order; undefined for lists that don't reload.
 */
export function useListStepEvents(data: { pages: readonly unknown[] } | undefined, targetId: string | undefined, reloadKey?: string | null): void {
  const shown = useRef(data ? { reloadKey, pages: data.pages.length } : null);
  useOnSettled(data, ({ pages }) => {
    const previous = shown.current;
    shown.current = { reloadKey, pages: pages.length };
    if (reloadKey !== undefined && previous?.reloadKey !== reloadKey) emitStepEvent("reload-applied", targetId);
    else if (previous && pages.length > previous.pages) emitStepEvent("continuation-applied", targetId);
  });
}
