import clsx from "clsx";
import { useRef } from "react";
import { defineMessages, useIntl } from "react-intl";
import type { ChipBarViewModel, ChipViewModel } from "../../model/innertube.gen";
import type { Endpoint } from "../../model/endpoints";
import { setEntity, useEntity } from "../../state/entities";
import { useImpression, logClick } from "../../logging/impressions";
import { useRunCommand } from "../../commands/useRunCommand";
import { ChipShape } from "./ChipShape";
import styles from "./ChipBar.module.css";

const messages = defineMessages({
  label: { id: "chips.label", defaultMessage: "Filters" },
});

interface ChipBarState {
  selectedIndex?: number;
}

function Chip({ data, selected, onSelect }: { data: ChipViewModel; selected: boolean; onSelect: () => void }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  return (
    <div ref={ref} className={styles.chip}>
      <ChipShape text={data.text} selected={selected} label={data.accessibilityLabel} onClick={onSelect} />
    </div>
  );
}

/**
 * A bar of filter chips described by a view model. When the bar has a state
 * entity, the selected chip is stored there, so the views that the chips
 * filter can read it too; otherwise the response's selection shows.
 */
export function ChipBar({ data, className }: { data: ChipBarViewModel; className?: string }) {
  const intl = useIntl();
  const runCommand = useRunCommand();
  const state = useEntity<ChipBarState>(data.chipBarStateEntityKey);
  const chips = data.chips.map((c) => c.chipViewModel);
  const selected = state?.selectedIndex ?? Math.max(0, chips.findIndex((c) => c.selected));
  return (
    <div className={clsx(styles.bar, className)} role="group" aria-label={intl.formatMessage(messages.label)} data-renderer="chipBarViewModel">
      {chips.map((chip, i) => (
        <Chip
          key={chip.loggingDirectives?.trackingParams ?? i}
          data={chip}
          selected={i === selected}
          onSelect={() => {
            if (i === selected) return;
            logClick(chip);
            if (data.chipBarStateEntityKey) setEntity(data.chipBarStateEntityKey, { ...state, selectedIndex: i });
            runCommand(chip.tapCommand?.innertubeCommand as Endpoint | undefined);
          }}
        />
      ))}
    </div>
  );
}
