import { useSyncExternalStore } from "react";

interface MediaQuery {
  list: MediaQueryList;
  subscribe: (onChange: () => void) => () => void;
}

// One MediaQueryList per query, with a subscribe function that stays the
// same across renders, so useSyncExternalStore subscribes only once.
const queries = new Map<string, MediaQuery>();

function mediaQuery(query: string): MediaQuery {
  let mq = queries.get(query);
  if (!mq) {
    const list = window.matchMedia(query);
    mq = {
      list,
      subscribe: (onChange) => {
        list.addEventListener("change", onChange);
        return () => list.removeEventListener("change", onChange);
      },
    };
    queries.set(query, mq);
  }
  return mq;
}

/** Whether the media query matches; re-renders when that changes. */
export function useMediaQuery(query: string): boolean {
  const { list, subscribe } = mediaQuery(query);
  return useSyncExternalStore(subscribe, () => list.matches);
}
