import type { Endpoint } from "../model/endpoints";
import type { ContinuationItemRenderer } from "../model/innertube.gen";
import { networkRequestFinished, networkRequestStarted } from "../logging/telemetry";

/** The page parameter of a continuation request: its token and click tracking. */
export interface PageParam {
  token: string;
  clickTrackingParams?: string;
}

/** Runs a request and reports its duration and outcome as a network request of the page. */
export async function measured<T>(page: string, request: "navigation" | "continuation", fetch: () => Promise<T>): Promise<T> {
  const timing = networkRequestStarted(page, request);
  try {
    const result = await fetch();
    networkRequestFinished(timing, true);
    return result;
  } catch (error) {
    networkRequestFinished(timing, false);
    throw error;
  }
}

/** The page parameter of a continuation command. */
export function commandParam(endpoint: Endpoint | null | undefined): PageParam | undefined {
  const token = endpoint?.continuationCommand?.token;
  return token ? { token, clickTrackingParams: endpoint.clickTrackingParams } : undefined;
}

/** The page parameter of a continuation item. */
export function continuationParam(item: ContinuationItemRenderer | null | undefined): PageParam | undefined {
  return commandParam(item?.continuationEndpoint as Endpoint | undefined);
}
