import { useLayoutEffect, useRef } from "react";
import { PlayerChrome, type PlayerDetails } from "./PlayerChrome";
import "./player.css";

/** The parts of a player response that the player shows. */
export interface PlayerData {
  videoDetails?: PlayerDetails;
  captions?: { playerCaptionsTracklistRenderer?: unknown };
}

export interface PlayerProps {
  response: PlayerData;
  width: number;
  height: number;
  /** The player element's id: movie_player on the watch page, c4-player on a channel. */
  playerId?: string;
}

/** The video player: React owns its container, the player library its chrome. */
export function Player({ response, width, height, playerId = "movie_player" }: PlayerProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const playerRef = useRef<PlayerChrome | null>(null);
  useLayoutEffect(() => {
    const player = new PlayerChrome(containerRef.current!, playerId);
    playerRef.current = player;
    return () => {
      player.destroy();
      playerRef.current = null;
    };
  }, [playerId]);
  useLayoutEffect(() => {
    const captions = response.captions?.playerCaptionsTracklistRenderer as { captionTracks?: unknown[] } | undefined;
    playerRef.current?.update(response.videoDetails ?? {}, !!captions?.captionTracks?.length);
  }, [response, playerId]);
  useLayoutEffect(() => {
    if (width) playerRef.current?.setSize(width, height);
  }, [width, height, playerId]);
  return <div ref={containerRef} className="ytr-player-container" />;
}
