import { PLAYER_CHROME_HTML } from "./chrome.gen";

// The player is its own library, as on YouTube: it builds and updates its
// DOM itself, outside React. The page gives it a container, the player
// response and a size.

export interface PlayerDetails {
  videoId?: string;
  title?: string;
  author?: string;
  lengthSeconds?: string;
}

let template: HTMLTemplateElement | null = null;

/** Formats seconds as m:ss or h:mm:ss. */
export function formatTime(seconds: number): string {
  const s = Math.max(0, Math.floor(seconds));
  const pad = (n: number) => (n < 10 ? `0${n}` : `${n}`);
  const h = Math.floor(s / 3600);
  const m = Math.floor(s / 60) % 60;
  return h ? `${h}:${pad(m)}:${pad(s % 60)}` : `${m}:${pad(s % 60)}`;
}

export class PlayerChrome {
  readonly root: HTMLElement;
  private width = 0;
  private height = 0;

  constructor(container: HTMLElement, id: string) {
    if (!template) {
      template = document.createElement("template");
      template.innerHTML = PLAYER_CHROME_HTML;
    }
    this.root = document.importNode(template.content, true).firstElementChild as HTMLElement;
    this.root.id = id;
    this.root.tabIndex = -1;
    container.appendChild(this.root);
  }

  /** Fills the chrome from the player response: title, channel, duration and captions. */
  update(details: PlayerDetails, hasCaptions: boolean): void {
    const setText = (selector: string, text: string) => {
      for (const el of this.root.querySelectorAll(selector)) el.textContent = text;
    };
    const length = Number(details.lengthSeconds) || 0;
    setText(".ytlp-title-link", details.title ?? "");
    setText(".ytlp-title-channel-name", details.author ?? "");
    setText(".ytlp-time-duration", formatTime(length));
    setText(".ytlp-time-current", "0:00");
    const bar = this.root.querySelector(".ytlp-progress-bar");
    if (bar) {
      bar.setAttribute("aria-valuemax", String(length));
      bar.setAttribute("aria-valuetext", `0:00 of ${formatTime(length)}`);
    }
    const subtitles = this.root.querySelector<HTMLButtonElement>(".ytlp-subtitles-button");
    if (subtitles) {
      subtitles.disabled = !hasCaptions;
      subtitles.setAttribute("aria-pressed", "false");
    }
    this.root.classList.toggle("ytlp-hide-info-bar", !details.title);
  }

  /** Sizes the video area and the bottom chrome. */
  setSize(width: number, height: number): void {
    if (width === this.width && height === this.height) return;
    this.width = width;
    this.height = height;
    this.root.style.width = `${width}px`;
    this.root.style.height = `${height}px`;
    const video = this.root.querySelector("video");
    if (video) {
      video.style.width = `${width}px`;
      video.style.height = `${height}px`;
      video.style.left = "0px";
      video.style.top = "0px";
    }
    for (const selector of [".ytlp-chrome-bottom", ".ytlp-progress-bar-container"]) {
      const el = this.root.querySelector<HTMLElement>(selector);
      if (el) el.style.width = `${width - 24}px`;
    }
  }

  destroy(): void {
    this.root.remove();
  }
}
