import clsx from "clsx";
import { defineMessages, useIntl } from "react-intl";
import styles from "./RetryMessage.module.css";

const messages = defineMessages({
  retry: { id: "feedback.retry", defaultMessage: "Retry" },
});

export interface RetryMessageProps {
  text: string;
  onRetry: () => void;
  className?: string;
}

/** A message that a part of the page failed to load, with a button that tries again. */
export function RetryMessage({ text, onRetry, className }: RetryMessageProps) {
  const intl = useIntl();
  return (
    <div role="alert" className={clsx(styles.message, className)}>
      <span>{text}</span>
      <button type="button" className={styles.button} onClick={onRetry}>
        {intl.formatMessage(messages.retry)}
      </button>
    </div>
  );
}
